import api from "./Axios";

// ─────────────────────────────────────────────────────────────────
// KYC API — all endpoints from the API doc
// Base: http://localhost:3001
// ─────────────────────────────────────────────────────────────────

// ── Auth ─────────────────────────────────────────────────────────

/** POST /api/auth/send-otp */
export const sendOtp = (mobile) =>
  api.post("/api/auth/send-otp", { mobile });

/** POST /api/auth/verify-otp */
export const verifyOtp = (mobile, otp) =>
  api.post("/api/auth/verify-otp", { mobile, otp });

/** POST /api/auth/register */
export const registerUser = (data) =>
  api.post("/api/auth/register", data);

/** POST /api/auth/login  (mobile + password) */
export const loginUser = (mobile, password) =>
  api.post("/api/auth/login", { mobile, password });

// ── KYC Document Upload ──────────────────────────────────────────

/** POST /api/kyc/upload-pan-documents  — multipart/form-data */
export const uploadPan = (file, token) => {
  const form = new FormData();
  form.append("panCard", file);
  return api.post("/api/kyc/upload-pan-documents", form, {
    headers: {
      "Content-Type": "multipart/form-data",
      Authorization: `Bearer ${token}`,
    },
  });
};

/** POST /api/kyc/upload-aadhar-documents  — multipart/form-data */
export const uploadAadhar = (aadharFront, selfie, token) => {
  const form = new FormData();
  form.append("aadharFront", aadharFront);
  form.append("selfie", selfie);
  return api.post("/api/kyc/upload-aadhar-documents", form, {
    headers: {
      "Content-Type": "multipart/form-data",
      Authorization: `Bearer ${token}`,
    },
  });
};

/** POST /api/kyc/upload-passport-documents  — multipart/form-data */
export const uploadPassport = (file, token) => {
  const form = new FormData();
  form.append("passport", file);
  return api.post("/api/kyc/upload-passport-documents", form, {
    headers: {
      "Content-Type": "multipart/form-data",
      Authorization: `Bearer ${token}`,
    },
  });
};

// ── KYC Review ───────────────────────────────────────────────────

/** POST /api/kyc/submit-for-review */
export const submitForReview = (token) =>
  api.post(
    "/api/kyc/submit-for-review",
    {},
    { headers: { Authorization: `Bearer ${token}` } }
  );

/** GET /api/kyc/verification-status */
export const getVerificationStatus = (token) =>
  api.get("/api/kyc/verification-status", {
    headers: { Authorization: `Bearer ${token}` },
  });

/** GET /api/kyc/review-pipeline-status */
export const getReviewPipelineStatus = (token) =>
  api.get("/api/kyc/review-pipeline-status", {
    headers: { Authorization: `Bearer ${token}` },
  });

// ── Admin KYC Actions ────────────────────────────────────────────
// These would be admin-side endpoints — update status on the backend.
// If your backend exposes them, use these:

/** Admin: Approve KYC for a user */
export const adminApproveKyc = (userId) =>
  api.post(`/api/admin/kyc/approve/${userId}`);

/** Admin: Reject KYC for a user */
export const adminRejectKyc = (userId, reason) =>
  api.post(`/api/admin/kyc/reject/${userId}`, { reason });

/** Admin: Get all KYC requests */
export const adminGetKycList = () =>
  api.get("/api/admin/kyc/list");

/** Admin: Get single user KYC details */
export const adminGetKycDetails = (userId) =>
  api.get(`/api/admin/kyc/user/${userId}`);
